import {transferCases,transferCorrect,profileCases,profileState,profileCorrect} from './energy-models.js?v=20261023-physicscomplete01';
import {showEnergy} from './energy-scenes.js?v=20261023-physicscomplete01';
const select=(id,label,opts)=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}"><option value="">Choose…</option>${opts.map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select>`;
export function mountEnergyWidget(l,p,root,{save,done,feedback}){const w=p.widget;w.task??=0;w.answers??={};w.passed??=[];const profiles=l.widget==='energy-profiles',cases=profiles?profileCases:transferCases,i=w.task%cases.length,t=cases[i],a=w.answers[t.id]??={};w.answers[t.id]=a;const $=s=>root.querySelector(s),valid=()=>profiles?profileCorrect(t,a):transferCorrect(t,a);
 root.innerHTML=`<p><b>${i+1} / ${cases.length} · ${profiles?'Build the profile':t.name}</b></p><p>${profiles?t.prompt:t.context+` Initial ${t.initial}°C; final ${t.final}°C.`}</p>`+(profiles?select('energy-products','Products relative to reactants',[['lower','Lower'],['higher','Higher']])+select('energy-peak','Barrier',[['90','Higher of the two barriers'],['65','Lower of the two barriers']])+select('energy-origin','Start of activation-energy arrow A',[['reactants','Reactant level'],['products','Product level'],['baseline','Axis baseline']]):'<label class="field-label" for="energy-change">Temperature change: final − initial (°C)</label><input class="lab-input" id="energy-change" type="number" step="any">'+select('energy-kind','Reaction type',[['exo','Exothermic'],['endo','Endothermic']])+select('energy-direction','Energy transfer',[['out','Reaction → surroundings'],['in','Surroundings → reaction']]))+`<button class="secondary" id="checkEnergy">Check ${profiles?'profile':'prediction'}</button><button class="secondary" id="nextEnergy">Next case →</button><p id="energyProgress">${w.passed.length} / ${cases.length} correct</p>`;
 const draw=()=>profiles?showEnergy('profile',undefined,true,{...profileState(a.products,a.peak),origin:a.origin||'reactants'}):showEnergy('transfer',t,w.passed.includes(t.id)&&valid());
 for(const key of profiles?['products','peak','origin']:['change','kind','direction']){const el=$('#energy-'+key);el.value=a[key]??'';el[el.tagName==='INPUT'?'oninput':'onchange']=e=>{a[key]=e.target.value;save();draw();};}draw();
 $('#checkEnergy').onclick=()=>{if(!valid()){feedback(profiles?'Match the requested endpoint levels and barrier. Activation energy starts at the reactant level, not the product level or axis baseline.':'Use final minus initial for the signed change. Warming surroundings means energy leaves the reacting system; cooling means energy enters it.',true);return;}if(!w.passed.includes(t.id))w.passed.push(t.id);save();draw();$('#energyProgress').textContent=`${w.passed.length} / ${cases.length} correct`;feedback(profiles?'Correct: your endpoints, barrier and activation comparison fit the challenge.':'Correct: the temperature change, reaction type and transfer direction agree.');if(w.passed.length===cases.length){p.widgetDone=true;save();done();}};
 $('#nextEnergy').onclick=()=>{w.task=(i+1)%cases.length;save();feedback('');mountEnergyWidget(l,p,root,{save,done,feedback});};}
